(2760217, 383970, 43565, '<td valign="top">Cute idea, but the hand drawn "Steve" next to the real flower just don''t go together to me.</td>', 'Cute idea, but the hand drawn "Steve" next to the real flower just don''t go together to me.', '2006-08-25 17:27:16.000000', NULL, 1),
